import React, { useEffect, useState } from "react";

export default function App() {
  const [authMode, setAuthMode] = useState("login");
  const [screen, setScreen] = useState("auth");
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [currentUser, setCurrentUser] = useState("");
  const [authError, setAuthError] = useState("");

  const [feeling, setFeeling] = useState("");
  const [mealInput, setMealInput] = useState("");
  const [mealFeeling, setMealFeeling] = useState("");
  const [meals, setMeals] = useState([]);

  useEffect(() => {
    const savedUser = localStorage.getItem("currentUser");
    if (savedUser) {
      setCurrentUser(savedUser);
      setScreen("home");
      loadUserMeals(savedUser);
    }
  }, []);

  useEffect(() => {
    if (currentUser) {
      localStorage.setItem(`meals_${currentUser}`, JSON.stringify(meals));
    }
  }, [meals, currentUser]);

  const loadUserMeals = (user) => {
    const savedMeals = localStorage.getItem(`meals_${user}`);
    if (savedMeals) {
      setMeals(JSON.parse(savedMeals));
    } else {
      setMeals([]);
    }
  };

  const getUsers = () => {
    const users = localStorage.getItem("users");
    return users ? JSON.parse(users) : [];
  };

  const saveUsers = (users) => {
    localStorage.setItem("users", JSON.stringify(users));
  };

  const registerUser = () => {
    setAuthError("");

    if (!username.trim() || !password.trim()) {
      setAuthError("יש למלא שם משתמש וסיסמה");
      return;
    }

    const users = getUsers();
    const exists = users.find((user) => user.username === username.trim());

    if (exists) {
      setAuthError("שם המשתמש כבר קיים");
      return;
    }

    const newUser = {
      username: username.trim(),
      password: password.trim(),
    };

    const updatedUsers = [...users, newUser];
    saveUsers(updatedUsers);

    localStorage.setItem("currentUser", newUser.username);
    setCurrentUser(newUser.username);
    setMeals([]);
    setScreen("home");
    setUsername("");
    setPassword("");
  };

  const loginUser = () => {
    setAuthError("");

    if (!username.trim() || !password.trim()) {
      setAuthError("יש למלא שם משתמש וסיסמה");
      return;
    }

    const users = getUsers();
    const foundUser = users.find(
      (user) =>
        user.username === username.trim() && user.password === password.trim()
    );

    if (!foundUser) {
      setAuthError("שם משתמש או סיסמה לא נכונים");
      return;
    }

    localStorage.setItem("currentUser", foundUser.username);
    setCurrentUser(foundUser.username);
    loadUserMeals(foundUser.username);
    setScreen("home");
    setUsername("");
    setPassword("");
  };

  const logoutUser = () => {
    localStorage.removeItem("currentUser");
    setCurrentUser("");
    setMeals([]);
    setFeeling("");
    setMealInput("");
    setMealFeeling("");
    setScreen("auth");
  };

  const saveMeal = () => {
    if (mealInput.trim() === "" || mealFeeling === "") return;

    const newMeal = {
      name: mealInput,
      feeling: mealFeeling,
    };

    setMeals([...meals, newMeal]);
    setMealInput("");
    setMealFeeling("");
    setScreen("home");
  };

  const deleteMeal = (indexToDelete) => {
    const updatedMeals = meals.filter((_, index) => index !== indexToDelete);
    setMeals(updatedMeals);
  };

  const feelingButtonStyle = (value, selectedValue) => ({
    padding: "12px 18px",
    borderRadius: "12px",
    border:
      selectedValue === value ? "2px solid #10b981" : "1px solid #d1d5db",
    backgroundColor: selectedValue === value ? "#ecfdf5" : "white",
    color: "#111827",
    fontSize: "16px",
    cursor: "pointer",
    minWidth: "90px",
    fontWeight: "500",
  });

  const mainButton = {
    padding: "14px 18px",
    borderRadius: "14px",
    border: "none",
    backgroundColor: "#10b981",
    color: "white",
    fontSize: "16px",
    fontWeight: "600",
    cursor: "pointer",
    width: "100%",
    marginTop: "16px",
  };

  const secondaryButton = {
    padding: "12px 18px",
    borderRadius: "14px",
    border: "1px solid #d1d5db",
    backgroundColor: "white",
    color: "#111827",
    fontSize: "16px",
    cursor: "pointer",
    width: "100%",
    marginTop: "12px",
  };

  const getFeelingColor = (value) => {
    if (value === "טוב") return "#16a34a";
    if (value === "סביר") return "#d97706";
    if (value === "לא טוב") return "#dc2626";
    return "#6b7280";
  };

  if (screen === "auth") {
    return (
      <div
        dir="rtl"
        style={{
          minHeight: "100vh",
          backgroundColor: "#f8fafc",
          fontFamily: "Arial, sans-serif",
          padding: "24px 16px",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div
          style={{
            maxWidth: "420px",
            width: "100%",
            backgroundColor: "white",
            borderRadius: "24px",
            padding: "24px",
            boxShadow: "0 10px 30px rgba(15,23,42,0.08)",
          }}
        >
          <h1 style={{ marginTop: 0, fontSize: "32px", color: "#111827" }}>
            {authMode === "login" ? "התחברות" : "הרשמה"}
          </h1>

          <p style={{ color: "#6b7280", marginBottom: "16px" }}>
            {authMode === "login"
              ? "התחבר כדי לראות את הנתונים שלך"
              : "פתח משתמש חדש בכמה שניות"}
          </p>

          <input
            placeholder="שם משתמש"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            style={{
              width: "100%",
              padding: "14px",
              borderRadius: "14px",
              border: "1px solid #d1d5db",
              fontSize: "16px",
              boxSizing: "border-box",
              marginBottom: "12px",
            }}
          />

          <input
            type="password"
            placeholder="סיסמה"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            style={{
              width: "100%",
              padding: "14px",
              borderRadius: "14px",
              border: "1px solid #d1d5db",
              fontSize: "16px",
              boxSizing: "border-box",
            }}
          />

          {authError && (
            <div
              style={{
                marginTop: "12px",
                color: "#dc2626",
                fontSize: "14px",
                backgroundColor: "#fef2f2",
                padding: "10px",
                borderRadius: "12px",
              }}
            >
              {authError}
            </div>
          )}

          <button
            style={mainButton}
            onClick={authMode === "login" ? loginUser : registerUser}
          >
            {authMode === "login" ? "התחבר" : "צור משתמש"}
          </button>

          <button
            style={secondaryButton}
            onClick={() =>
              setAuthMode(authMode === "login" ? "register" : "login")
            }
          >
            {authMode === "login"
              ? "אין לי משתמש עדיין"
              : "כבר יש לי משתמש"}
          </button>
        </div>
      </div>
    );
  }

  return (
    <div
      dir="rtl"
      style={{
        minHeight: "100vh",
        backgroundColor: "#f8fafc",
        fontFamily: "Arial, sans-serif",
        padding: "24px 16px",
      }}
    >
      <div
        style={{
          maxWidth: "420px",
          margin: "0 auto",
        }}
      >
        {screen === "home" && (
          <>
            <div
              style={{
                background: "linear-gradient(135deg, #10b981, #34d399)",
                color: "white",
                borderRadius: "24px",
                padding: "24px",
                boxShadow: "0 10px 30px rgba(16,185,129,0.18)",
                marginBottom: "18px",
              }}
            >
              <div
                style={{ fontSize: "14px", opacity: 0.95, marginBottom: "8px" }}
              >
                שלום {currentUser}
              </div>
              <h1 style={{ margin: 0, fontSize: "34px", lineHeight: "1.2" }}>
                מה בטוח לי לאכול היום?
              </h1>
            </div>

            <div
              style={{
                backgroundColor: "white",
                borderRadius: "20px",
                padding: "20px",
                boxShadow: "0 6px 20px rgba(15,23,42,0.06)",
                marginBottom: "16px",
              }}
            >
              <h3
                style={{
                  marginTop: 0,
                  marginBottom: "14px",
                  fontSize: "22px",
                  color: "#111827",
                }}
              >
                איך אתה מרגיש היום?
              </h3>

              <div
                style={{
                  display: "flex",
                  gap: "10px",
                  flexWrap: "wrap",
                  marginBottom: "14px",
                }}
              >
                <button
                  style={feelingButtonStyle("טוב", feeling)}
                  onClick={() => setFeeling("טוב")}
                >
                  טוב
                </button>
                <button
                  style={feelingButtonStyle("סביר", feeling)}
                  onClick={() => setFeeling("סביר")}
                >
                  סביר
                </button>
                <button
                  style={feelingButtonStyle("לא טוב", feeling)}
                  onClick={() => setFeeling("לא טוב")}
                >
                  לא טוב
                </button>
              </div>

              <div
                style={{
                  fontSize: "15px",
                  color: "#4b5563",
                  backgroundColor: "#f9fafb",
                  borderRadius: "12px",
                  padding: "12px",
                }}
              >
                מצב נוכחי: <strong>{feeling || "עוד לא נבחר"}</strong>
              </div>
            </div>

            <div
              style={{
                backgroundColor: "white",
                borderRadius: "20px",
                padding: "20px",
                boxShadow: "0 6px 20px rgba(15,23,42,0.06)",
                marginBottom: "16px",
              }}
            >
              <h3
                style={{
                  marginTop: 0,
                  marginBottom: "14px",
                  fontSize: "22px",
                  color: "#111827",
                }}
              >
                מה כדאי לך לאכול היום
              </h3>

              <div style={{ display: "grid", gap: "10px" }}>
                <div
                  style={{
                    backgroundColor: "#f0fdf4",
                    border: "1px solid #bbf7d0",
                    borderRadius: "14px",
                    padding: "14px",
                    fontSize: "16px",
                  }}
                >
                  אורז עם עוף
                </div>
                <div
                  style={{
                    backgroundColor: "#f0fdf4",
                    border: "1px solid #bbf7d0",
                    borderRadius: "14px",
                    padding: "14px",
                    fontSize: "16px",
                  }}
                >
                  מרק ירקות
                </div>
                <div
                  style={{
                    backgroundColor: "#f0fdf4",
                    border: "1px solid #bbf7d0",
                    borderRadius: "14px",
                    padding: "14px",
                    fontSize: "16px",
                  }}
                >
                  חביתה
                </div>
              </div>

              <button style={mainButton} onClick={() => setScreen("add")}>
                הוספת ארוחה
              </button>
            </div>

            <div
              style={{
                backgroundColor: "white",
                borderRadius: "20px",
                padding: "20px",
                boxShadow: "0 6px 20px rgba(15,23,42,0.06)",
                marginBottom: "16px",
              }}
            >
              <h3
                style={{
                  marginTop: 0,
                  marginBottom: "14px",
                  fontSize: "22px",
                  color: "#111827",
                }}
              >
                מה אכלתי היום
              </h3>

              {meals.length === 0 ? (
                <p style={{ color: "#6b7280", margin: 0 }}>
                  עדיין לא הוספת ארוחות
                </p>
              ) : (
                <div style={{ display: "grid", gap: "10px" }}>
                  {meals.map((meal, index) => (
                    <div
                      key={index}
                      style={{
                        border: "1px solid #e5e7eb",
                        borderRadius: "14px",
                        padding: "12px",
                        backgroundColor: "#f9fafb",
                      }}
                    >
                      <div
                        style={{
                          fontSize: "16px",
                          fontWeight: "600",
                          color: "#111827",
                        }}
                      >
                        {meal.name}
                      </div>

                      <div
                        style={{
                          marginTop: "6px",
                          fontSize: "14px",
                          fontWeight: "500",
                          color: getFeelingColor(meal.feeling),
                        }}
                      >
                        הרגשתי אחרי זה: {meal.feeling}
                      </div>

                      <button
                        onClick={() => deleteMeal(index)}
                        style={{
                          marginTop: "10px",
                          backgroundColor: "#fee2e2",
                          color: "#dc2626",
                          border: "none",
                          padding: "8px 12px",
                          borderRadius: "10px",
                          cursor: "pointer",
                          fontSize: "14px",
                        }}
                      >
                        מחק
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>

            <button style={secondaryButton} onClick={logoutUser}>
              התנתק
            </button>
          </>
        )}

        {screen === "add" && (
          <div
            style={{
              backgroundColor: "white",
              borderRadius: "20px",
              padding: "20px",
              boxShadow: "0 6px 20px rgba(15,23,42,0.06)",
            }}
          >
            <h1 style={{ marginTop: 0, fontSize: "30px", color: "#111827" }}>
              הוספת ארוחה
            </h1>

            <p style={{ color: "#6b7280", marginBottom: "14px" }}>
              כתוב מה אכלת ואיך הרגשת אחריה
            </p>

            <input
              placeholder="מה אכלת?"
              value={mealInput}
              onChange={(e) => setMealInput(e.target.value)}
              style={{
                width: "100%",
                padding: "14px",
                borderRadius: "14px",
                border: "1px solid #d1d5db",
                fontSize: "16px",
                boxSizing: "border-box",
                marginBottom: "16px",
              }}
            />

            <h3
              style={{
                marginTop: 0,
                marginBottom: "12px",
                fontSize: "20px",
                color: "#111827",
              }}
            >
              איך הרגשת אחרי האוכל?
            </h3>

            <div
              style={{
                display: "flex",
                gap: "10px",
                flexWrap: "wrap",
                marginBottom: "8px",
              }}
            >
              <button
                style={feelingButtonStyle("טוב", mealFeeling)}
                onClick={() => setMealFeeling("טוב")}
              >
                טוב
              </button>
              <button
                style={feelingButtonStyle("סביר", mealFeeling)}
                onClick={() => setMealFeeling("סביר")}
              >
                סביר
              </button>
              <button
                style={feelingButtonStyle("לא טוב", mealFeeling)}
                onClick={() => setMealFeeling("לא טוב")}
              >
                לא טוב
              </button>
            </div>

            <button style={mainButton} onClick={saveMeal}>
              שמור ארוחה
            </button>

            <button style={secondaryButton} onClick={() => setScreen("home")}>
              חזור למסך הבית
            </button>
          </div>
        )}
      </div>
    </div>
  );
}
